function ClickAreaMgr:clickScene(startPos, endPos)
    if TableUtil.isEmpty(self.allClickArea) then
        return
    end
    local ray = { startPos, endPos }
    ---@type ClickArea[]
    local clickAreas = {}
    for _, clickAreaList in pairs(self.allClickArea) do
        for _, clickArea in pairs(clickAreaList) do
            if CollectionUtil.intersectWithAABB(clickArea.area, ray) then
                table.insert(clickAreas, clickArea)
            end
        end
    end
    local minDistance = 9999999
    ---@type ClickArea
    local nearestArea
    for _, clickArea in pairs(clickAreas) do
        local distance = VectorUtil.distance(clickArea.area:getCenterPos(), endPos)
        if distance < minDistance then
            nearestArea = clickArea
            minDistance = distance
        end
    end
    if nearestArea then
        nearestArea.func()
    end
end

