    if type(func) ~= "function" then
        return
    end
    local list = self.allClickArea[key] or {}
    table.insert(list, { area = area, func = func })
    self.allClickArea[key] = list
end

function ClickAreaMgr:clearClickArea(key)
    self.allClickArea[key] = nil
end

